from pathlib import Path

p = Path('out/SpecialMainBridge.cpp')
s = p.read_text(encoding='utf-8')

old = '''    std::uint64_t gGpuDraws = 0;\n    std::uint64_t gFallbackDraws = 0;\n\n    struct Record\n    {\n        float (*bones)[3][4] = nullptr;\n        int boneCount = 0;\n        bool translate = false;\n        float restScale = 0.0f;\n        float boneScale = 1.0f;\n        float lightDir[3] = {0.f,-1.5f,0.f};\n        std::uint32_t serial = 0;\n    };'''
new = '''    std::uint64_t gGpuDraws = 0;\n    std::uint64_t gFallbackDraws = 0;\n    std::uint64_t gSkippedVertices = 0;\n    std::uint64_t gSkippedNormals = 0;\n    std::uint64_t gLazyCpuMeshTransforms = 0;\n\n    struct Record\n    {\n        float (*bones)[3][4] = nullptr;\n        int boneCount = 0;\n        bool translate = false;\n        float restScale = 0.0f;\n        float boneScale = 1.0f;\n        float lightDir[3] = {0.f,-1.5f,0.f};\n        std::uint32_t serial = 0;\n        float bbMin[3] = {0.f,0.f,0.f};\n        float bbMax[3] = {0.f,0.f,0.f};\n        void* obb = nullptr;\n        std::vector<unsigned char> skipped;\n        std::vector<unsigned char> cpuReady;\n    };'''
assert old in s, 'record block not found'
s = s.replace(old, new, 1)

marker = '''    bool TryGpuRender(BMDSpecial* self,int i,int renderFlag,float alpha,int blendMesh,float blendLight,float u,float v,int meshTexture)\n    {'''
helper = '''    bool MeshGpuCandidate(BMDSpecial* self, int i)\n    {\n        if (!gEnabled || !gGpuMeshes || !self || !self->Meshs || !self->IndexTexture) return false;\n        if (self->NumBones <= 0 || self->NumBones > 200 || i < 0 || i >= self->NumMeshs) return false;\n        MeshSpecial* m = &self->Meshs[i];\n        if (m->NumTriangles <= 0 || m->NumVertices <= 0 || m->NumNormals <= 0 || !m->Vertices || !m->Normals || !m->TexCoords || !m->Triangles) return false;\n        if (m->TextureScript != nullptr) return false;\n        int texture = self->IndexTexture[m->Texture];\n        if (texture==BITMAP_HIDE || texture==BITMAP_SKIN || texture==BITMAP_WATER || texture==BITMAP_HAIR) return false;\n        return IsOpaqueTexture(texture);\n    }\n\n    bool TryGpuRender(BMDSpecial* self,int i,int renderFlag,float alpha,int blendMesh,float blendLight,float u,float v,int meshTexture)\n    {'''
assert marker in s, 'TryGpuRender marker not found'
s = s.replace(marker, helper, 1)

old_log = '''        if ((gGpuDraws % 10000u)==0u) Log("GPU draws=%llu fallback=%llu records=%u",\n            static_cast<unsigned long long>(gGpuDraws), static_cast<unsigned long long>(gFallbackDraws), static_cast<unsigned>(gRecords.size()));'''
new_log = '''        if ((gGpuDraws % 10000u)==0u) Log("GPU draws=%llu fallback=%llu skippedV=%llu skippedN=%llu lazyCPU=%llu records=%u",\n            static_cast<unsigned long long>(gGpuDraws), static_cast<unsigned long long>(gFallbackDraws),\n            static_cast<unsigned long long>(gSkippedVertices), static_cast<unsigned long long>(gSkippedNormals),\n            static_cast<unsigned long long>(gLazyCpuMeshTransforms), static_cast<unsigned>(gRecords.size()));'''
assert old_log in s, 'log block not found'
s = s.replace(old_log, new_log, 1)

old_hook = '''    void __fastcall HookTransform(BMDSpecial* self, void*, float (*bones)[3][4], float* bbMin, float* bbMax, void* obb, bool translate, float restScale)\n    {\n        ReadConfig();\n        gOriginalTransform(self,bones,bbMin,bbMax,obb,translate,restScale);\n        if (!gEnabled || !self || !bones) return;\n        Record& r=gRecords[self];\n        r.bones=bones;\n        r.boneCount=self->NumBones;\n        r.translate=translate;\n        r.restScale=restScale;\n        __try { r.boneScale=*reinterpret_cast<volatile float*>(kBoneScale); }\n        __except(EXCEPTION_EXECUTE_HANDLER) { r.boneScale=1.f; }\n        ComputeLightDir(self,r.lightDir);\n        r.serial=++gSerial;\n    }\n\n    void __fastcall HookRenderMesh(BMDSpecial* self, void*, int i, int renderFlag, float alpha, int blendMesh, float blendLight, float u, float v, int meshTexture)\n    {\n        ReadConfig();\n        TryDisableVsync();\n        if (TryGpuRender(self,i,renderFlag,alpha,blendMesh,blendLight,u,v,meshTexture)) return;\n        ++gFallbackDraws;\n        gOriginalRenderMesh(self,i,renderFlag,alpha,blendMesh,blendLight,u,v,meshTexture);\n    }'''
new_hook = '''    void __fastcall HookTransform(BMDSpecial* self, void*, float (*bones)[3][4], float* bbMin, float* bbMax, void* obb, bool translate, float restScale)\n    {\n        ReadConfig();\n        if (!self || !bones)\n        {\n            gOriginalTransform(self,bones,bbMin,bbMax,obb,translate,restScale);\n            return;\n        }\n\n        Record& r = gRecords[self];\n        const int meshCount = (self->NumMeshs > 0 && self->NumMeshs < 512) ? self->NumMeshs : 0;\n        r.skipped.assign(static_cast<std::size_t>(meshCount), 0);\n        r.cpuReady.assign(static_cast<std::size_t>(meshCount), 1);\n\n        std::vector<short> savedVertices(static_cast<std::size_t>(meshCount));\n        std::vector<short> savedNormals(static_cast<std::size_t>(meshCount));\n        if (gEnabled && gGpuMeshes && meshCount > 0 && self->Meshs && self->NumBones > 0 && self->NumBones <= 200)\n        {\n            for (int i=0; i<meshCount; ++i)\n            {\n                MeshSpecial& m = self->Meshs[i];\n                savedVertices[static_cast<std::size_t>(i)] = m.NumVertices;\n                savedNormals[static_cast<std::size_t>(i)] = m.NumNormals;\n                if (MeshGpuCandidate(self,i))\n                {\n                    r.skipped[static_cast<std::size_t>(i)] = 1;\n                    r.cpuReady[static_cast<std::size_t>(i)] = 0;\n                    gSkippedVertices += static_cast<unsigned short>(m.NumVertices);\n                    gSkippedNormals += static_cast<unsigned short>(m.NumNormals);\n                    m.NumVertices = 0;\n                    m.NumNormals = 0;\n                }\n            }\n        }\n\n        gOriginalTransform(self,bones,bbMin,bbMax,obb,translate,restScale);\n\n        for (int i=0; i<meshCount; ++i)\n        {\n            if (r.skipped[static_cast<std::size_t>(i)])\n            {\n                self->Meshs[i].NumVertices = savedVertices[static_cast<std::size_t>(i)];\n                self->Meshs[i].NumNormals = savedNormals[static_cast<std::size_t>(i)];\n            }\n        }\n\n        r.bones=bones;\n        r.boneCount=self->NumBones;\n        r.translate=translate;\n        r.restScale=restScale;\n        r.obb=obb;\n        if (bbMin) { r.bbMin[0]=bbMin[0]; r.bbMin[1]=bbMin[1]; r.bbMin[2]=bbMin[2]; }\n        if (bbMax) { r.bbMax[0]=bbMax[0]; r.bbMax[1]=bbMax[1]; r.bbMax[2]=bbMax[2]; }\n        __try { r.boneScale=*reinterpret_cast<volatile float*>(kBoneScale); }\n        __except(EXCEPTION_EXECUTE_HANDLER) { r.boneScale=1.f; }\n        ComputeLightDir(self,r.lightDir);\n        r.serial=++gSerial;\n    }\n\n    bool EnsureCpuMesh(BMDSpecial* self, int target)\n    {\n        auto it = gRecords.find(self);\n        if (it == gRecords.end() || !self || !self->Meshs) return false;\n        Record& r = it->second;\n        if (target < 0 || target >= self->NumMeshs || static_cast<std::size_t>(target) >= r.cpuReady.size()) return false;\n        if (r.cpuReady[static_cast<std::size_t>(target)]) return true;\n        if (!r.bones) return false;\n\n        const int meshCount = self->NumMeshs;\n        std::vector<short> nv(static_cast<std::size_t>(meshCount));\n        std::vector<short> nn(static_cast<std::size_t>(meshCount));\n        for (int i=0; i<meshCount; ++i)\n        {\n            nv[static_cast<std::size_t>(i)] = self->Meshs[i].NumVertices;\n            nn[static_cast<std::size_t>(i)] = self->Meshs[i].NumNormals;\n            if (i != target)\n            {\n                self->Meshs[i].NumVertices = 0;\n                self->Meshs[i].NumNormals = 0;\n            }\n        }\n\n        gOriginalTransform(self,r.bones,r.bbMin,r.bbMax,r.obb,r.translate,r.restScale);\n\n        for (int i=0; i<meshCount; ++i)\n        {\n            self->Meshs[i].NumVertices = nv[static_cast<std::size_t>(i)];\n            self->Meshs[i].NumNormals = nn[static_cast<std::size_t>(i)];\n        }\n        r.cpuReady[static_cast<std::size_t>(target)] = 1;\n        ++gLazyCpuMeshTransforms;\n        return true;\n    }\n\n    void __fastcall HookRenderMesh(BMDSpecial* self, void*, int i, int renderFlag, float alpha, int blendMesh, float blendLight, float u, float v, int meshTexture)\n    {\n        ReadConfig();\n        TryDisableVsync();\n        if (TryGpuRender(self,i,renderFlag,alpha,blendMesh,blendLight,u,v,meshTexture)) return;\n        EnsureCpuMesh(self,i);\n        ++gFallbackDraws;\n        gOriginalRenderMesh(self,i,renderFlag,alpha,blendMesh,blendLight,u,v,meshTexture);\n    }'''
assert old_hook in s, 'hook block not found'
s = s.replace(old_hook, new_hook, 1)

p.write_text(s, encoding='utf-8')
print('SpecialMainBridge v2 lazy CPU bypass patched')
